import { useEffect, useState } from "react";
import "./Staff.css";

export const Staff = () => {
  const [data, setdata] = useState([]);
  useEffect(() => {
    fetch("https://reqres.in/api/users")
      .then((res) => res.json())
      .then((res) => setdata(res.data));
  },[]);
  console.log(data);

  return (
    <div>
      <p>Staff</p>
    </div>
  );
};
